33	const (
34		// ReplaceAll replaces the entire leaf directory contents with the new entries.
35		ReplaceAll MergeMode = iota
36		// MergeKeepExisting merges new entries into the existing leaf directory,
37		// keeping existing entries that are not overwritten (unless in DeleteNames).
38		MergeKeepExisting
