198	
199	// ApplyTreeChanges applies multiple file-level changes to a tree efficiently.
200	// Changes are grouped by directory and applied in a single recursive pass.
201	// Unchanged subdirectories retain their hashes — this is the key optimization
202	// over FlattenTree + BuildTreeFromEntries for sparse changes.
203	func ApplyTreeChanges(
204		ctx context.Context,
205		repo *git.Repository,
206		rootTreeHash plumbing.Hash,
207		changes []TreeChange,
208	) (plumbing.Hash, error) {
209		if len(changes) == 0 {
210			return rootTreeHash, nil
211		}
212	
213		var currentEntries []object.TreeEntry
214		if rootTreeHash != plumbing.ZeroHash {
215			tree, err := repo.TreeObject(rootTreeHash)
216			if err != nil {
217				cliEntries, cliErr := readTreeEntriesViaCLI(ctx, rootTreeHash)
218				if cliErr != nil {
219					return plumbing.ZeroHash, fmt.Errorf("failed to read tree: %w", errors.Join(err, cliErr))
220				}
221				logging.Warn(ctx, "ApplyTreeChanges: go-git tree read failed, used git ls-tree fallback",
222					slog.String("tree", rootTreeHash.String()[:12]),
223					slog.String("gogit_error", err.Error()),
224				)
225				currentEntries = cliEntries
226			} else {
227				currentEntries = make([]object.TreeEntry, len(tree.Entries))
228				copy(currentEntries, tree.Entries)
229			}
230		}
231	
232		// Group changes by first path segment
233		type dirChanges struct {
234			subChanges []TreeChange // Changes within this subdirectory
235			fileChange *TreeChange  // Direct file change at this level (nil if none)
236		}
237		grouped := make(map[string]*dirChanges)
238	
239		for i := range changes {
240			c := changes[i]
241			normalizedPath, err := normalizeGitTreePath(c.Path)
242			if err != nil {
243				logInvalidGitTreePath(ctx, "apply tree change", c.Path, err)
244				continue
245			}
246	
247			first, rest := splitFirstSegment(normalizedPath)
248			if grouped[first] == nil {
249				grouped[first] = &dirChanges{}
250			}
251			if rest == "" {
252				cc := c
253				cc.Path = normalizedPath
254				grouped[first].fileChange = &cc
255			} else {
256				grouped[first].subChanges = append(grouped[first].subChanges, TreeChange{
257					Path:  rest,
258					Entry: c.Entry,
259				})
260			}
261		}
262	
263		// Build entry map for modifications
264		entryMap := make(map[string]object.TreeEntry, len(currentEntries))
265		for _, e := range currentEntries {
266			entryMap[e.Name] = e
267		}
268	
269		// Process each group
270		for name, dc := range grouped {
271			if dc.fileChange != nil {
272				if dc.fileChange.Entry == nil {
273					delete(entryMap, name)
274				} else {
275					entryMap[name] = object.TreeEntry{
276						Name: name,
277						Mode: dc.fileChange.Entry.Mode,
278						Hash: dc.fileChange.Entry.Hash,
279					}
280				}
281			}
282			if len(dc.subChanges) > 0 {
283				existingHash := plumbing.ZeroHash
284				if existing, ok := entryMap[name]; ok && existing.Mode == filemode.Dir {
285					existingHash = existing.Hash
286				}
287				newSubHash, err := ApplyTreeChanges(ctx, repo, existingHash, dc.subChanges)
288				if err != nil {
289					return plumbing.ZeroHash, fmt.Errorf("failed to apply changes in %s: %w", name, err)
290				}
291				entryMap[name] = object.TreeEntry{
292					Name: name,
293					Mode: filemode.Dir,
294					Hash: newSubHash,
295				}
296			}
297		}
298	
299		result := make([]object.TreeEntry, 0, len(entryMap))
300		for _, e := range entryMap {
301			result = append(result, e)
302		}
303		sortTreeEntries(result)
304		return storeTree(repo, result)
305	}
306	
307	// readTreeEntriesViaCLI parses `git ls-tree <hash>` into go-git TreeEntry
308	// values. Fallback for go-git tree reads that fail in partial-clone repos
309	// where the storer's packfile index has gone stale — analogous to the
310	// blob-side workaround in FetchingTree.blobOnDisk.
311	func readTreeEntriesViaCLI(ctx context.Context, hash plumbing.Hash) ([]object.TreeEntry, error) {
312		short := hash.String()[:12]
313		cmd := exec.CommandContext(ctx, "git", "ls-tree", hash.String())
314		output, err := cmd.Output()
315		if err != nil {
316			return nil, fmt.Errorf("git ls-tree %s: %w", short, err)
317		}
318		trimmed := strings.TrimRight(string(output), "\n")
319		if trimmed == "" {
320			return nil, nil
321		}
322		lines := strings.Split(trimmed, "\n")
323		entries := make([]object.TreeEntry, 0, len(lines))
324		for _, line := range lines {
325			// Format: "<mode> <type> <hash>\t<name>"
326			tab := strings.IndexByte(line, '\t')
327			if tab < 0 {
328				return nil, fmt.Errorf("git ls-tree %s: malformed line %q", short, line)
329			}
330			name := line[tab+1:]
331			fields := strings.Fields(line[:tab])
332			if len(fields) != 3 {
333				return nil, fmt.Errorf("git ls-tree %s: malformed entry %q", short, line)
334			}
335			mode, modeErr := filemode.New(fields[0])
336			if modeErr != nil {
337				return nil, fmt.Errorf("git ls-tree %s: invalid mode %q: %w", short, fields[0], modeErr)
338			}
339			entries = append(entries, object.TreeEntry{
340				Name: name,
341				Mode: mode,
342				Hash: plumbing.NewHash(fields[2]),
343			})
344		}
345		return entries, nil
346	}
347	
348	// WalkCheckpointShards iterates over the two-level shard structure (<id[:2]>/<id[2:]>/)
349	// in a checkpoint tree, calling fn for each checkpoint found. It skips non-directory
350	// and non-shard entries at both levels, such as legacy generation.json files or
351	// other metadata kept outside shard directories. The callback receives the parsed
352	// checkpoint ID and the tree hash of the checkpoint subtree.
353	func WalkCheckpointShards(ctx context.Context, repo *git.Repository, tree *object.Tree, fn func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error) error {
354		for _, bucketEntry := range tree.Entries {
355			if err := ctx.Err(); err != nil {
356				return err //nolint:wrapcheck // propagate context cancellation unwrapped
357			}
358			if bucketEntry.Mode != filemode.Dir {
359				continue
360			}
361			if len(bucketEntry.Name) != 2 {
362				continue
363			}
364	
365			bucketTree, err := repo.TreeObject(bucketEntry.Hash)
366			if err != nil {
367				continue
368			}
369	
370			if err := ctx.Err(); err != nil {
371				return err //nolint:wrapcheck // propagate context cancellation unwrapped
372			}
373			for _, cpEntry := range bucketTree.Entries {
374				if cpEntry.Mode != filemode.Dir {
375					continue
376				}
377	
378				cpID, err := id.NewCheckpointID(bucketEntry.Name + cpEntry.Name)
379				if err != nil {
380					continue
381				}
382	
383				if err := fn(cpID, cpEntry.Hash); err != nil {
384					return err
385				}
386			}
387		}
388		return nil
389	}
390	
391	func normalizeGitTreePath(path string) (string, error) {
392		if path == "" {
393			return "", errors.New("path is empty")
394		}
395	
396		path = filepath.ToSlash(path)
397		if isAbsoluteGitTreePath(path) {
398			return "", errors.New("path must be relative")
399		}
400	
401		parts := strings.Split(path, "/")
402		for _, part := range parts {
403			if part == "" {
404				return "", errors.New("path contains empty segment")
405			}
406			if part == "." || part == ".." {
407				return "", fmt.Errorf("path contains invalid segment %q", part)
408			}
409		}
410	
411		return path, nil
412	}
413	
414	func isAbsoluteGitTreePath(path string) bool {
415		if filepath.IsAbs(path) {
416			return true
417		}
418	
419		if len(path) >= 3 && path[1] == ':' && path[2] == '/' {
420			drive := path[0]
421			return (drive >= 'a' && drive <= 'z') || (drive >= 'A' && drive <= 'Z')
422		}
423	
424		return false
425	}
426	
427	func logInvalidGitTreePath(ctx context.Context, operation, path string, err error) {
428		logging.Warn(ctx, "skipping invalid git tree path",
429			slog.String("operation", operation),
430			slog.String("path", path),
431			slog.String("error", err.Error()),
432		)
433	}
434	
435	// splitFirstSegment splits "a/b/c" into ("a", "b/c"), and "file.txt" into ("file.txt", "").
436	func splitFirstSegment(path string) (first, rest string) {
437		parts := strings.SplitN(path, "/", 2)
438		if len(parts) == 1 {
439			return parts[0], ""
440		}
441		return parts[0], parts[1]
442	}
443	
444	// getSessionsBranchRef returns the primary metadata ref's commit hash and root tree
445	// hash without flattening the tree.
446	func (s *GitStore) getSessionsBranchRef() (plumbing.Hash, plumbing.Hash, error) {
447		ref, err := s.repo.Reference(s.refs.Primary, true)
448		if err != nil {
449			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get primary metadata ref %s: %w", s.refs.Primary, err)
450		}
451	
452		parentCommit, err := s.repo.CommitObject(ref.Hash())
453		if err != nil {
454			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
455		}
456	
457		return ref.Hash(), parentCommit.TreeHash, nil
458	}
