}

// Log file changes
logFileChanges(ctx, relModifiedFiles, relNewFiles, relDeletedFiles)

// Get git author
author, err := GetGitAuthor(ctx)
if err != nil {
	return fmt.Errorf("failed to get git author: %w", err)
}

